/**
 * Golden path demo test. Generated by demo-path-verify (setup mode).
 * Each owner edits only the demoStep(...) block of their own step.
 *
 * GOLDEN PATH (copied from .claude/state/golden-path.md, used for drift detection):
 * 1. Open the app → first-run residence onboarding; choose under 6 months, press 다음 and see 관심 활동 with 탐험 시작 (owner: Byeunghee02)
 * 2. Press 탐험 시작 → onboarding saves the search (내 동네 start, today 14:00, 10 km; no setup page) → actual score map for 25 dongs; all 20 displayed places contribute; pending evidence is labelled (owner: chowonbhin)
 * 3. Click 본오1동 → 20 actual search places, measured review counts, linked markers and 20/20 scored places on a fixed 0–100 scale (owner: iwtkmn0219)
 * 4. Record 바바카멜 visit → real score recalculates; 자기 신고 and 지역 Lv.1 appear (owner: zT4ek)
 * 5. Return and reload → scores and visit persist; the full actual candidate pool remains available (owner: zT4ek)
 */
import { test, expect, type Page } from '@playwright/test';
import fs from 'node:fs';
import path from 'node:path';

const BASE_URL = process.env.BASE_URL ?? 'http://localhost:3000';
const EVIDENCE_DIR = process.env.EVIDENCE_DIR ?? '.claude/state/evidence/manual';
fs.mkdirSync(EVIDENCE_DIR, { recursive: true });

const VISITED = '바바카멜';

let stepNo = 0;
const RUN = process.env.RUN_INDEX ?? '1';

/**
 * One golden-path step: act, assert what is visible, time it, screenshot it.
 * `pending`: the step is still a placeholder (give the owner). It only walks through the
 * placeholder screen and is reported as PENDING, never as PASS. Remove it when the step is real.
 */
async function demoStep(
  page: Page,
  name: string,
  fn: () => Promise<void>,
  opts: { budgetMs?: number; pending?: string } = {},
) {
  const budgetMs = opts.budgetMs ?? 1500;
  stepNo += 1;
  const n = String(stepNo).padStart(2, '0');
  const shot = path.join(EVIDENCE_DIR, `run${RUN}-step-${n}.png`);
  const t0 = Date.now();
  let status = 'PASS';
  let error: string | undefined;
  try {
    await test.step(name, fn);
  } catch (e) {
    status = 'FAIL';
    error = String(e).split('\n')[0];
    throw e;
  } finally {
    const ms = Date.now() - t0;
    if (status === 'PASS' && ms > budgetMs) status = 'SLOW';
    if (status === 'PASS' && opts.pending) status = 'PENDING';
    let shotOk = true;
    await page.screenshot({ path: shot, fullPage: true }).catch(() => (shotOk = false));
    fs.appendFileSync(
      path.join(EVIDENCE_DIR, 'steps.jsonl'),
      JSON.stringify({ run: RUN, step: stepNo, name, status, ms, budgetMs, shot, shotOk, pending: opts.pending, error }) + '\n',
    );
  }
}

test('golden path', async ({ page }) => {
  const consoleErrors: string[] = [];
  page.on('console', m => m.type() === 'error' && consoleErrors.push(m.text()));
  page.on('pageerror', e => consoleErrors.push(String(e)));
  let beforeScore = 0;
  let afterScore = 0;
  let otherScores: Record<string, string> = {};
  const mapScore = () => page.locator('[data-region-id="dong-4127154000"]');
  const others = () => page.locator('[data-region-id]:not([data-region-id="dong-4127154000"])').evaluateAll(nodes =>
    Object.fromEntries(nodes.map(node => [node.getAttribute('data-region-id')!, node.getAttribute('data-score')!])));
  try {
    await page.goto(BASE_URL);
    await page.evaluate(() => localStorage.clear());
    await demoStep(page, '1. Open first-run onboarding → residence and 탐험 시작', async () => {
      await page.goto(BASE_URL);
      await expect(page.getByRole('heading', { level: 1 })).toContainText('안산');
      await page.getByRole('radio', { name: /6개월이 안 됐어요/ }).click();
      await page.getByRole('button', { name: '다음', exact: true }).click();
      await expect(page.getByRole('group', { name: '관심 활동' })).toBeVisible();
      await expect(page.getByRole('button', { name: '탐험 시작' })).toBeVisible();
    }, { budgetMs: 3000 });
    await demoStep(page, '2. Set conditions → actual score and 25 administrative dongs', async () => {
      // Onboarding saves the search itself: 내 동네 start (default 중앙역), today 14:00, 10 km.
      await page.getByRole('button', { name: '탐험 시작' }).click();
      await expect(page.locator('[data-region-id]')).toHaveCount(25);
      beforeScore = Number(await mapScore().getAttribute('data-score'));
      expect(beforeScore).toBeGreaterThan(0);
      // The map shows familiarity and today's picks; scores stay in data-score, 20 places are checked in step 3.
      await expect(page.getByRole('button', { name: /^지도 본오1동/ })).toHaveAccessibleName(/오늘의 추천 \d+순위/);
      await expect(page.getByRole('button', { name: /^지도 중앙동/ })).toHaveAccessibleName(/오늘의 추천 \d+순위/);
      await expect(page.locator('.recommend')).not.toContainText('점수');
      otherScores = await others();
      await page.getByRole('region', { name: '안산 탐험 지도' }).scrollIntoViewIfNeeded();
    }, { budgetMs: 3000 });
    await demoStep(page, '3. Click 본오1동 → 20 real places, real reviews and linked markers', async () => {
      await page.getByRole('button', { name: /^지도 본오1동/ }).focus();
      await page.keyboard.press('Enter');
      const places = page.getByRole('list', { name: '행정동 장소 추천' });
      await expect(places.locator(':scope > li')).toHaveCount(20);
      await expect(places).not.toContainText('시연용 가상');
      await expect(places).toContainText('방문자 리뷰 수 801건');
      await expect(places).not.toContainText('점수');
      // No pins until a place is chosen; choosing its photo pins only that place on the map.
      const map = page.getByRole('region', { name: '안산 탐험 지도' });
      await expect(map.getByRole('button', { name: /지도에서 선택$/ })).toHaveCount(0);
      await page.getByRole('button', { name: '바바카멜 카드에서 선택', exact: true }).click();
      await expect(map.getByRole('button', { name: /지도에서 선택$/ })).toHaveCount(1);
      await expect(map.getByRole('button', { name: '바바카멜 지도에서 선택', exact: true })).toHaveAttribute('aria-pressed', 'true');
      await expect(page.getByRole('button', { name: '바바카멜 카드에서 선택', exact: true })).toHaveAttribute('aria-pressed', 'true');
      await page.getByRole('region', { name: '안산 탐험 지도' }).scrollIntoViewIfNeeded();
    });
    await demoStep(page, '4. Record a real visit → score recomputation and Lv.1 with 20 places retained', async () => {
      const panel = page.getByRole('region', { name: `${VISITED} 방문 기록`, exact: true });
      await panel.getByLabel('방문일', { exact: true }).fill('2026-11-08');
      await panel.getByRole('button', { name: '방문 기록', exact: true }).click();
      await expect(page.getByRole('list', { name: '행정동 장소 추천' }).locator(':scope > li')).toHaveCount(20);
      await page.getByRole('button', { name: '가본 장소', exact: true }).click();
      // Lv is no longer printed; the panel keeps it as a hidden data hook.
      await expect(panel).toHaveAttribute('data-region-level', '1');
      await expect(panel.getByText('다녀왔어요', { exact: true })).toBeVisible();
      await expect(panel.locator('time')).toHaveText('2026-11-08');
    });
    await demoStep(page, '5. Return and reload → same real score, source counts and visit persist', async () => {
      await page.getByRole('link', { name: '안산에 스며들다' }).click();
      afterScore = Number(await mapScore().getAttribute('data-score'));
      expect(afterScore).toBeLessThan(beforeScore);
      expect(await others()).toEqual(otherScores);
      await page.reload();
      await expect(mapScore()).toHaveAttribute('data-score', String(afterScore));
      await page.getByRole('button', { name: /^지도 본오1동/ }).focus();
      await page.keyboard.press('Enter');
      await page.getByRole('button', { name: '가본 장소', exact: true }).click();
      const panel = page.getByRole('region', { name: `${VISITED} 방문 기록`, exact: true });
      await expect(panel.locator('time')).toHaveText('2026-11-08');
      // Lv is no longer printed; the panel keeps it as a hidden data hook.
      await expect(panel).toHaveAttribute('data-region-level', '1');
      await page.getByRole('link', { name: '안산에 스며들다' }).click();
      await expect(page.getByRole('heading', { name: '추천 행정동', exact: true })).toBeVisible();
      await page.getByRole('region', { name: '안산 탐험 지도' }).scrollIntoViewIfNeeded();
    });
  } finally {
    fs.appendFileSync(path.join(EVIDENCE_DIR, 'console-errors.txt'), consoleErrors.map(e => `[run${RUN}] ${e}`).join('\n') + (consoleErrors.length ? '\n' : ''));
  }
});
